import {
  toggleSubcontractorCompanySignUpUrl,
  type SubcontractorCompanyDetailsResponse,
  type ToggleSubcontractorCompanySignUpUrlResponse,
} from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useSubcontractorCompanySignUpUrlToggle = defineMutation(() => {
  const queryCache = useQueryCache();

  function setCachedEnabled(companyId: string, enabled: boolean) {
    queryCache.setQueryData(['subcontractor-company', companyId], (oldData?: SubcontractorCompanyDetailsResponse) => {
      if (!oldData) return oldData;
      return { ...oldData, sign_up_url_enabled: enabled };
    });
  }

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: { companyId: string; enabled: boolean }): Promise<ToggleSubcontractorCompanySignUpUrlResponse> =>
      toggleSubcontractorCompanySignUpUrl({
        composable: '$fetch',
        path: { subcontractor_company_id: vars.companyId },
        body: { enabled: vars.enabled },
      }),
    onMutate: ({ companyId, enabled }) => {
      setCachedEnabled(companyId, enabled);
    },
    onSuccess: (_, { enabled }) => {
      showToastSuccess(enabled ? 'Sign-up URL enabled successfully' : 'Sign-up URL disabled successfully');
    },
    onError(error, { companyId, enabled }) {
      showToastError(error);
      setCachedEnabled(companyId, !enabled);
    },
  });

  return {
    subcontractorCompanySignUpUrlToggle: mutateAsync,
    isSubcontractorCompanySignUpUrlToggleLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
