import {
  regenerateSubcontractorCompanySignUpCode,
  type RegenerateSubcontractorCompanySignUpCodeResponse,
  type SubcontractorCompanyDetailsResponse,
} from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useSubcontractorCompanySignUpCodeRegenerate = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: { companyId: string }): Promise<RegenerateSubcontractorCompanySignUpCodeResponse> =>
      regenerateSubcontractorCompanySignUpCode({
        composable: '$fetch',
        path: { subcontractor_company_id: vars.companyId },
      }),
    onSuccess: (data, { companyId }) => {
      showToastSuccess('Sign-up URL regenerated successfully');
      queryCache.setQueryData(['subcontractor-company', companyId], (oldData?: SubcontractorCompanyDetailsResponse) => {
        if (!oldData) return oldData;
        return { ...oldData, sign_up_url: data.sign_up_url };
      });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    subcontractorCompanySignUpCodeRegenerate: mutateAsync,
    isSubcontractorCompanySignUpCodeRegenerateLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
