<template>
  <Card v-if="!note && !isNoteDraft">
    <CardHeader>
      <CardTitle>Note</CardTitle>
    </CardHeader>
    <CardContent>
      <p class="text-sm text-muted-foreground">
        No note has been created for this subcontractor yet. You can add a note to keep track of important information.
      </p>
    </CardContent>
    <CardFooter>
      <Button variant="outline" :prepend-icon="NotebookPenIcon" @click="changeNoteDraft">Create a Note</Button>
    </CardFooter>
  </Card>
  <EntityNote
    v-else
    :note="note"
    :is-note-draft="isNoteDraft"
    :change-note-draft="changeNoteDraft"
    :update-note="onUpdate"
    :remove-note="onRemove"
    :is-update-loading="isSubcontractorCompanyNoteUpsertLoading"
    :is-remove-loading="isSubcontractorCompanyNoteRemoveLoading"
    form-description="This note is visible to other administrators"
  />
</template>

<script setup lang="ts">
import { NotebookPenIcon } from 'lucide-vue-next';
import type { Note } from '~/client';
import { useSubcontractorCompanyNoteUpsert } from '~/mutations/subcontractor-company/notes/upsert';
import { useSubcontractorCompanyNoteRemove } from '~/mutations/subcontractor-company/notes/remove';

const props = defineProps<{
  companyId: string;
  note: Note | null;
  isNoteDraft: boolean;
  changeNoteDraft: () => void;
}>();

const { subcontractorCompanyNoteUpsert, isSubcontractorCompanyNoteUpsertLoading } = useSubcontractorCompanyNoteUpsert();
const { subcontractorCompanyNoteRemove, isSubcontractorCompanyNoteRemoveLoading } = useSubcontractorCompanyNoteRemove();

async function onUpdate(content: string) {
  await subcontractorCompanyNoteUpsert({ companyId: props.companyId, content });
}

async function onRemove() {
  await subcontractorCompanyNoteRemove({ companyId: props.companyId });
}
</script>
