import {
  upsertSubcontractorCompanyNote,
  type SubcontractorCompanyDetailsResponse,
  type UpsertSubcontractorCompanyNoteResponse,
} from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useSubcontractorCompanyNoteUpsert = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: { companyId: string; content: string }): Promise<UpsertSubcontractorCompanyNoteResponse> =>
      upsertSubcontractorCompanyNote({
        composable: '$fetch',
        path: { subcontractor_company_id: vars.companyId },
        body: { content: vars.content },
      }),
    onSuccess: (data, { companyId }) => {
      showToastSuccess('Note saved successfully');
      queryCache.setQueryData(['subcontractor-company', companyId], (oldData?: SubcontractorCompanyDetailsResponse) => {
        if (!oldData) return oldData;
        return { ...oldData, note: data.note };
      });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    subcontractorCompanyNoteUpsert: mutateAsync,
    isSubcontractorCompanyNoteUpsertLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
