<template>
  <Card>
    <CardHeader>
      <div class="flex items-center justify-between gap-2">
        <CardTitle>Sign-up URL</CardTitle>
        <div v-if="!isCompanyDeactivated" class="flex items-center gap-2">
          <Label for="subcontractor-signup-toggle" class="text-xs text-muted-foreground">
            {{ enabled ? 'Enabled' : 'Disabled' }}
          </Label>
          <Switch
            id="subcontractor-signup-toggle"
            :model-value="enabled"
            :disabled="isSubcontractorCompanySignUpUrlToggleLoading"
            @update:model-value="onToggle"
          >
            <template #thumb>
              <Spinner v-if="isSubcontractorCompanySignUpUrlToggleLoading" class="w-5 h-5 fill-foreground" />
            </template>
          </Switch>
        </div>
      </div>
    </CardHeader>
    <CardContent class="flex flex-col gap-3">
      <Alert v-if="isCompanyDeactivated" variant="info">
        <Info />
        <AlertDescription>
          Sign-up is not available for deactivated companies. Activate the company to manage the sign-up URL.
        </AlertDescription>
      </Alert>
      <template v-else>
        <p class="text-sm text-muted-foreground">
          {{
            enabled
              ? 'Share this unique link with the company so new subcontractor canvassers can sign up.'
              : 'Sign-up is disabled. New subcontractor canvassers cannot register using this link until you enable it again.'
          }}
        </p>
        <div class="flex items-center gap-2">
          <Input
            :model-value="signUpUrl"
            readonly
            :disabled="!enabled || isSubcontractorCompanySignUpCodeRegenerateLoading"
            class="font-mono text-xs"
          />
          <Button
            variant="outline"
            size="icon"
            aria-label="Copy URL"
            :disabled="!enabled || isSubcontractorCompanySignUpCodeRegenerateLoading"
            @click="onCopy"
          >
            <Check v-if="isCopied" class="h-4 w-4" />
            <Copy v-else class="h-4 w-4" />
          </Button>
        </div>
        <ConfirmationDialog
          title="Regenerate URL?"
          description="The previous sign-up link will stop working. New subcontractor canvassers will need the new URL."
          confirm-btn-text="Regenerate"
          @confirm="onRegenerate"
        >
          <Button
            variant="outline"
            :prepend-icon="RefreshCw"
            :disabled="!enabled"
            :loading="isSubcontractorCompanySignUpCodeRegenerateLoading"
            class="self-start"
          >
            Regenerate URL
          </Button>
        </ConfirmationDialog>
      </template>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { Check, Copy, Info, RefreshCw } from 'lucide-vue-next';
import ConfirmationDialog from '~/components/common/ConfirmationDialog.vue';
import { useSubcontractorCompanySignUpUrlToggle } from '~/mutations/subcontractor-company/signUpUrl/toggle';
import { useSubcontractorCompanySignUpCodeRegenerate } from '~/mutations/subcontractor-company/signUpCode/regenerate';
import { showToastError } from '~/utils/show-toast';
import { Spinner } from '~/assets/icons';
import type { SubcontractorCompanyStatus } from '~/client';

const props = defineProps<{
  companyId: string;
  signUpUrl: string;
  enabled: boolean;
  companyStatus: SubcontractorCompanyStatus;
}>();

const isCompanyDeactivated = computed(() => props.companyStatus === 'deactivated');

const { subcontractorCompanySignUpUrlToggle, isSubcontractorCompanySignUpUrlToggleLoading } =
  useSubcontractorCompanySignUpUrlToggle();
const { subcontractorCompanySignUpCodeRegenerate, isSubcontractorCompanySignUpCodeRegenerateLoading } =
  useSubcontractorCompanySignUpCodeRegenerate();

const isCopied = ref(false);
let copyResetTimer: ReturnType<typeof setTimeout> | null = null;

onBeforeUnmount(() => {
  if (copyResetTimer) clearTimeout(copyResetTimer);
});

async function onCopy() {
  if (typeof navigator === 'undefined' || !navigator.clipboard) {
    showToastError(undefined, 'Clipboard not available');
    return;
  }
  try {
    await navigator.clipboard.writeText(props.signUpUrl);
    isCopied.value = true;
    if (copyResetTimer) clearTimeout(copyResetTimer);
    copyResetTimer = setTimeout(() => {
      isCopied.value = false;
    }, 1500);
  } catch {
    showToastError(undefined, 'Failed to copy');
  }
}

async function onToggle(value: boolean) {
  await subcontractorCompanySignUpUrlToggle({ companyId: props.companyId, enabled: value });
}

async function onRegenerate() {
  await subcontractorCompanySignUpCodeRegenerate({ companyId: props.companyId });
}
</script>
