import {
  changeSubcontractorCompanyStatus,
  type SubcontractorCompanyDetailsResponse,
  type SubcontractorCompanyStatus,
  type ChangeSubcontractorCompanyStatusResponse,
} from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useSubcontractorCompanyStatusChange = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: {
      companyId: string;
      status: SubcontractorCompanyStatus;
      isOpen?: Ref<boolean, boolean>;
    }): Promise<ChangeSubcontractorCompanyStatusResponse> =>
      changeSubcontractorCompanyStatus({
        composable: '$fetch',
        path: { subcontractor_company_id: vars.companyId },
        body: { status: vars.status },
      }),
    onSuccess: (res, { companyId, isOpen }) => {
      if (isOpen) isOpen.value = false;
      queryCache.setQueryData(['subcontractor-company', companyId], (oldData?: SubcontractorCompanyDetailsResponse) =>
        oldData
          ? {
              ...oldData,
              status: res.status,
              // Backend disables the sign-up URL when a company is deactivated and leaves it
              // disabled on reactivation; mirror that here so the sign-up card isn't stale.
              sign_up_url_enabled: res.status === 'deactivated' ? false : oldData.sign_up_url_enabled,
            }
          : oldData
      );
      showToastSuccess(res.status === 'active' ? 'Company activated successfully' : 'Company deactivated successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    subcontractorCompanyStatusChange: mutateAsync,
    isSubcontractorCompanyStatusChangeLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
