<template>
  <Card>
    <CardHeader>
      <CardTitle>Danger Zone</CardTitle>
    </CardHeader>
    <CardContent>
      <p class="text-accent-foreground leading-7">
        Company status
        <Badge :variant="statusEntry.variant" class="w-fit inline-block">
          {{ statusEntry.label }}
        </Badge>
      </p>
    </CardContent>
    <CardFooter class="flex flex-wrap gap-4 justify-start">
      <ConfirmationDialog2
        v-model="isOpen"
        :title="statusAction.title"
        :description="statusAction.description"
        :confirm-btn-variant="statusAction.confirmBtnVariant"
        :confirm-btn-text="statusAction.actionText"
        :is-confirm-loading="isSubcontractorCompanyStatusChangeLoading"
        :is-awaited-close="true"
        :confirm="
          async () => {
            await onChangeStatus();
          }
        "
      >
        <Button
          :variant="statusAction.buttonVariant"
          :disabled="isSubcontractorCompanyStatusChangeLoading"
          class="h-10 px-3"
        >
          {{ statusAction.actionText }}
        </Button>
      </ConfirmationDialog2>
    </CardFooter>
  </Card>
</template>

<script lang="ts" setup>
import type { SubcontractorCompanyStatus } from '~/client';
import { useSubcontractorCompanyStatusChange } from '~/mutations/subcontractor-company/status/change';
import { getSubcontractorCompanyStatus } from '~/constants/subcontractor-companies/statusConfig';

const props = defineProps<{
  companyId: string;
  status: SubcontractorCompanyStatus;
}>();

const statusActionConfig = {
  active: {
    title: 'Deactivate company?',
    description: 'Are you sure you want to deactivate this company? Sign-up and related actions will be turned off.',
    actionText: 'Deactivate Company',
    confirmBtnVariant: 'destructive',
    buttonVariant: 'outline-destructive',
  },
  deactivated: {
    title: 'Activate company?',
    description: 'Are you sure you want to activate this company?',
    actionText: 'Activate Company',
    confirmBtnVariant: 'default',
    buttonVariant: 'outline',
  },
} as const;

const { subcontractorCompanyStatusChange, isSubcontractorCompanyStatusChangeLoading } =
  useSubcontractorCompanyStatusChange();

const isActive = computed(() => props.status === 'active');
const statusAction = computed(() => statusActionConfig[props.status]);
const statusEntry = computed(() => getSubcontractorCompanyStatus(props.status));
const isOpen = ref(false);

async function onChangeStatus() {
  if (isSubcontractorCompanyStatusChangeLoading.value) return;
  await subcontractorCompanyStatusChange({
    companyId: props.companyId,
    status: isActive.value ? 'deactivated' : 'active',
    isOpen,
  });
}
</script>
