import {
  deleteSubcontractorCompanyNote,
  type DeleteSubcontractorCompanyNoteResponse,
  type SubcontractorCompanyDetailsResponse,
} from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useSubcontractorCompanyNoteRemove = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: { companyId: string }): Promise<DeleteSubcontractorCompanyNoteResponse> =>
      deleteSubcontractorCompanyNote({
        composable: '$fetch',
        path: { subcontractor_company_id: vars.companyId },
      }),
    onSuccess: (_, { companyId }) => {
      showToastSuccess('Note removed successfully');
      queryCache.setQueryData(['subcontractor-company', companyId], (oldData?: SubcontractorCompanyDetailsResponse) => {
        if (!oldData) return oldData;
        return { ...oldData, note: null };
      });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    subcontractorCompanyNoteRemove: mutateAsync,
    isSubcontractorCompanyNoteRemoveLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
